// ---------------------------------------------------------------------------
// T-101 process model — Northwind, Rotterdam terminal.
//
// One tank, one modulating inlet valve, two pumps in duty/standby with
// rotation on every start. Level is integrated properly from a mass balance
// rather than faked with a sine wave, because the whole point of the lab is
// that the screen is driven by something that behaves like a plant.
//
//   dV/dt = Qin - Qout          V volume m3, Q m3/h
//   level = V / (area * height) * 100
//
// Runs on a 500 ms tick. dt is taken from the clock, not assumed, so a slow
// tick does not silently change the process gain.
// ---------------------------------------------------------------------------

var s = context.get('s');
if (!s) {
    s = {
        // geometry
        area: 7.07, height: 5.0,          // m2, m  -> 35.35 m3
        volume: 12.0,                     // m3 start ~34%
        // valve
        valveCmd: 65, valvePos: 65,       // %
        valveMaxFlow: 40,                 // m3/h at 100%
        // pumps
        duty: 'A',
        pumps: { A: {run:false, spd:0, hrs:1284.5, fault:false, rated:60},
                 B: {run:false, spd:0, hrs:1197.2, fault:false, rated:60} },
        // setpoints
        spStart: 78, spStop: 32,          // pump start / stop level %
        spLL: 10, spL: 20, spH: 80, spHH: 90,
        mode: 'AUTO',
        manualPumpA: false, manualPumpB: false,
        last: Date.now(),
        totaliser: 0
    };
}


// --- apply any pending writeback from the HMI, once, at the top of the tick ---
var c = flow.get('cmd');
if (c) {
    if (c.valveCmd    !== undefined) { s.valveCmd = c.valveCmd; }
    if (c.spStart     !== undefined) { s.spStart  = c.spStart; }
    if (c.spStop      !== undefined) { s.spStop   = c.spStop; }
    if (c.mode        !== undefined) { s.mode     = c.mode; }
    if (c.manualPumpA !== undefined) { s.manualPumpA = c.manualPumpA; }
    if (c.manualPumpB !== undefined) { s.manualPumpB = c.manualPumpB; }
    if (c.faultA      !== undefined) { s.pumps.A.fault = c.faultA; }
    if (c.faultB      !== undefined) { s.pumps.B.fault = c.faultB; }
    flow.set('cmd', null);
}

var now = Date.now();
var dt = (now - s.last) / 1000;            // seconds
if (dt <= 0 || dt > 5) { dt = 0.5; }       // guard against clock jumps
s.last = now;
// TIME COMPRESSION. The physics below are real; the clock is not. At true
// rates a full duty cycle on this tank takes ~35 minutes, which makes for a
// dead screen. SPEED=20 compresses it to roughly three minutes without
// touching the equations — every flow, level and totaliser figure remains
// dimensionally correct, it just happens twenty times faster.
var SPEED = 20;
var dth = (dt / 3600) * SPEED;             // hours (compressed)

// --- inlet valve: first-order travel, 12 %/s full stroke ---
var err = s.valveCmd - s.valvePos;
var step = Math.min(Math.abs(err), 12 * dt);
s.valvePos += Math.sign(err) * step;
s.valvePos = Math.max(0, Math.min(100, s.valvePos));

var level = (s.volume / (s.area * s.height)) * 100;

// --- pump control ---
var A = s.pumps.A, B = s.pumps.B;
if (s.mode === 'AUTO') {
    var anyRunning = A.run || B.run;
    if (!anyRunning && level >= s.spStart) {
        // rotate duty on every start so runtime hours stay even
        s.duty = (s.duty === 'A') ? 'B' : 'A';
        var d = s.pumps[s.duty];
        if (!d.fault) { d.run = true; }
        else { s.pumps[s.duty === 'A' ? 'B' : 'A'].run = true; }   // standby picks up
    }
    if (anyRunning && level <= s.spStop) { A.run = false; B.run = false; }
    // a faulted pump drops out and the standby takes over immediately
    ['A','B'].forEach(function(k){
        if (s.pumps[k].fault && s.pumps[k].run) {
            s.pumps[k].run = false;
            var o = (k === 'A') ? 'B' : 'A';
            if (!s.pumps[o].fault && level > s.spStop) { s.pumps[o].run = true; }
        }
    });
} else {
    A.run = s.manualPumpA && !A.fault;
    B.run = s.manualPumpB && !B.fault;
}

// --- pump speed ramp + runtime hours ---
['A','B'].forEach(function(k){
    var p = s.pumps[k];
    var target = p.run ? 100 : 0;
    var d2 = target - p.spd;
    p.spd += Math.sign(d2) * Math.min(Math.abs(d2), 45 * dt);   // ~2.2 s to full
    p.spd = Math.max(0, Math.min(100, p.spd));
    if (p.spd > 1) { p.hrs += dth; }
});

// --- mass balance ---
var qin  = s.valveMaxFlow * (s.valvePos / 100);
var qout = (A.rated * A.spd / 100) + (B.rated * B.spd / 100);
s.volume += (qin - qout) * dth;

// hard physical limits — a tank cannot go negative or overflow past 100%
var vmax = s.area * s.height;
if (s.volume < 0) { s.volume = 0; qout = qin; }
if (s.volume > vmax) { s.volume = vmax; }
s.totaliser += qout * dth;

level = (s.volume / vmax) * 100;

// --- alarms ---
var aLL = level <= s.spLL, aL = level <= s.spL;
var aH  = level >= s.spH,  aHH = level >= s.spHH;
var anyAlarm = aLL || aHH || A.fault || B.fault;

context.set('s', s);

function r(v, n) { return Math.round(v * Math.pow(10, n)) / Math.pow(10, n); }
var B_ = 'northwind/rotterdam/T101/';
var out = [
    { topic: B_+'level',            payload: r(level,2) },
    { topic: B_+'volume',           payload: r(s.volume,2) },
    { topic: B_+'inflow',           payload: r(qin,2) },
    { topic: B_+'outflow',          payload: r(qout,2) },
    { topic: B_+'totaliser',        payload: r(s.totaliser,1) },
    { topic: B_+'valve/position',   payload: r(s.valvePos,1) },
    { topic: B_+'valve/command',    payload: r(s.valveCmd,1) },
    { topic: B_+'pumpA/running',    payload: A.run ? 1 : 0 },
    { topic: B_+'pumpA/speed',      payload: r(A.spd,1) },
    { topic: B_+'pumpA/hours',      payload: r(A.hrs,1) },
    { topic: B_+'pumpA/fault',      payload: A.fault ? 1 : 0 },
    { topic: B_+'pumpB/running',    payload: B.run ? 1 : 0 },
    { topic: B_+'pumpB/speed',      payload: r(B.spd,1) },
    { topic: B_+'pumpB/hours',      payload: r(B.hrs,1) },
    { topic: B_+'pumpB/fault',      payload: B.fault ? 1 : 0 },
    { topic: B_+'duty',             payload: s.duty },
    { topic: B_+'mode',             payload: s.mode },
    { topic: B_+'setpoint/start',   payload: s.spStart },
    { topic: B_+'setpoint/stop',    payload: s.spStop },
    { topic: B_+'setpoint/LL',      payload: s.spLL },
    { topic: B_+'setpoint/HH',      payload: s.spHH },
    { topic: B_+'alarm/LL',         payload: aLL ? 1 : 0 },
    { topic: B_+'alarm/L',          payload: aL ? 1 : 0 },
    { topic: B_+'alarm/H',          payload: aH ? 1 : 0 },
    { topic: B_+'alarm/HH',         payload: aHH ? 1 : 0 },
    { topic: B_+'alarm/active',     payload: anyAlarm ? 1 : 0 }
];
return [out];

// Writeback from FUXA. Topic tail decides the target; everything is clamped
// here rather than trusting the HMI, because an operator screen is an input
// device and inputs get validated at the process end.
var tail = msg.topic.split('/cmd/')[1];
var v = parseFloat(msg.payload);
var t = String(msg.payload).trim().toUpperCase();

var p = {};
if (tail === 'valve')          { p.valveCmd = Math.max(0, Math.min(100, v)); }
else if (tail === 'setpoint/start') { p.spStart = Math.max(0, Math.min(100, v)); }
else if (tail === 'setpoint/stop')  { p.spStop  = Math.max(0, Math.min(100, v)); }
else if (tail === 'mode')      { p.mode = (t === 'MANUAL') ? 'MANUAL' : 'AUTO'; }
else if (tail === 'pumpA')     { p.manualPumpA = (v === 1 || t === 'TRUE'); }
else if (tail === 'pumpB')     { p.manualPumpB = (v === 1 || t === 'TRUE'); }
else if (tail === 'pumpA/fault') { p.faultA = (v === 1 || t === 'TRUE'); }
else if (tail === 'pumpB/fault') { p.faultB = (v === 1 || t === 'TRUE'); }
else { return null; }

flow.set('cmd', p);
node.status({fill:'blue', shape:'dot', text: tail + ' = ' + msg.payload});
return null;
